use aap::caps::http_client;

struct Node;

/// The hosts this node's `HTTPClient<[...]>` handle is scoped to. A URL outside
/// this set is a trap at the host boundary, so it is refused here instead and
/// reported as a fetch failure. Trapping would discard the whole batch.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an http(s) URL, or `None` if the URL is not of a shape
/// we are willing to hand to the host. Anything ambiguous is rejected.
fn host_of(url: &str) -> Option<&str> {
    // Reject whitespace and control characters outright.
    if url.bytes().any(|b| b <= b' ' || b == 0x7f) {
        return None;
    }
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    // Userinfo (`user@host`) makes the real host ambiguous; refuse it.
    if authority.contains('@') {
        return None;
    }
    let host = authority.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS.iter().any(|a| host.eq_ignore_ascii_case(a)),
        None => false,
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "url is not an allowlisted http(s) host".to_string(),
                });
                continue;
            }

            // `fetch` returns transport failures as values; only out-of-scope
            // requests trap, and the allowlist check above keeps those from occurring.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
